const lab=db.getSiblingDB("forge_lab");
const c=lab.getCollection("aula33");c.deleteMany({});
c.updateOne({_id:"preparo"},{$set:{tipo:"preparo"}},{upsert:true});
const stream=c.watch([{$match:{operationType:"insert"}}],{maxAwaitTimeMS:1000});
try{
 stream.tryNext(); // Inicializa o cursor antes da escrita que será observada.
 c.insertOne({_id:"evento",valor:7});
 let ev=null;const limite=Date.now()+10000;
 while(!ev&&Date.now()<limite)ev=stream.tryNext();
 if(!ev)throw new Error("evento não observado no prazo do laboratório");
 print(ev.operationType+":"+ev.fullDocument.valor);
 print(ev._id!==undefined?"token recebido":"sem token");
}finally{stream.close();}

